class Solution {
public:
    vector<int> eventualSafeNodes(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<vector<int>> revAdj(n);
        vector<int> outdegree(n, 0);
        for (int u = 0; u < n; ++u) {
            outdegree[u] = graph[u].size();
            for (int v : graph[u]) {
                revAdj[v].push_back(u);
            }
        }
        queue<int> q;
        for (int i = 0; i < n; ++i) {
            if (outdegree[i] == 0) q.push(i);
        }
        vector<bool> safe(n, false);
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            safe[node] = true;
            for (int prev : revAdj[node]) {
                if (--outdegree[prev] == 0) q.push(prev);
            }
        }
        vector<int> res;
        for (int i = 0; i < n; ++i) {
            if (safe[i]) res.push_back(i);
        }
        return res;
    }
};

class Solution {
    public List<Integer> eventualSafeNodes(int[][] graph) {
        int n = graph.length;
        List<List<Integer>> revAdj = new ArrayList<>();
        for (int i = 0; i < n; i++) revAdj.add(new ArrayList<>());
        int[] outdegree = new int[n];
        for (int u = 0; u < n; u++) {
            outdegree[u] = graph[u].length;
            for (int v : graph[u]) {
                revAdj.get(v).add(u);
            }
        }
        Queue<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (outdegree[i] == 0) q.add(i);
        }
        boolean[] safe = new boolean[n];
        while (!q.isEmpty()) {
            int node = q.poll();
            safe[node] = true;
            for (int prev : revAdj.get(node)) {
                if (--outdegree[prev] == 0) q.add(prev);
            }
        }
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (safe[i]) res.add(i);
        }
        return res;
    }
}

var eventualSafeNodes = function(graph) {
    const n = graph.length;
    const revAdj = Array.from({ length: n }, () => []);
    const outdegree = new Array(n).fill(0);
    for (let u = 0; u < n; u++) {
        outdegree[u] = graph[u].length;
        for (const v of graph[u]) {
            revAdj[v].push(u);
        }
    }
    const q = [];
    for (let i = 0; i < n; i++) {
        if (outdegree[i] === 0) q.push(i);
    }
    const safe = new Array(n).fill(false);
    let head = 0;
    while (head < q.length) {
        const node = q[head++];
        safe[node] = true;
        for (const prev of revAdj[node]) {
            outdegree[prev]--;
            if (outdegree[prev] === 0) q.push(prev);
        }
    }
    const res = [];
    for (let i = 0; i < n; i++) {
        if (safe[i]) res.push(i);
    }
    return res;
};
